<span class="line"><span class="__shiki_140thh">    time_bucket(INTERVAL </span><span class="__shiki_mdbnqw">&#39;1 hour&#39;</span><span class="__shiki_140thh">, </span><span class="__shiki_1itgoe">time</span><span class="__shiki_140thh">) </span><span class="__shiki_1itgoe">AS</span><span class="__shiki_1itgoe"> hour</span><span class="__shiki_140thh">,</span></span>
